[metadata] {"type": "create", "filePath": "/app/src/main/java/com/example/customers/domain/CustomerFilter.java", "content": "package com.example.customers.domain;

import java.text.Normalizer;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.function.Predicate;
import java.util.regex.Pattern;

/**
 * How the customer list is narrowed down: free text matched against names, and a
 * set of statuses.
 *
 * <p>This is a backend concern, not a UI one: {@link CustomerRepository} applies
 * the filter while it pages and while it counts, so the caller never has to hold
 * more than one page of rows.
 *
 * <p>A customer matches when it satisfies both parts:
 * <ul>
 * <li><b>Name</b> &mdash; {@link #name()} is split on whitespace, and every term
 * has to occur in the first or the last name. Comparison ignores case and
 * accents in both directions, so {@code makinen} and {@code mäkinen} both find
 * {@code Mäkinen}. Empty text matches everything.</li>
 * <li><b>Status</b> &mdash; an empty {@link #statuses()} matches every status;
 * otherwise the customer's status has to be one of them.</li>
 * </ul>
 *
 * @param name     the name terms, whitespace around them insignificant
 * @param statuses the statuses to keep, empty for all of them
 */
public record CustomerFilter(String name, Set<CustomerStatus> statuses) {

