+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Collections;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.function.Predicate;
+import java.util.regex.Pattern;
+
+/**
+ * How the customer list is narrowed down: free text matched against names, and a
+ * set of statuses.
+ *
+ * <p>This is a backend concern, not a UI one: {@link CustomerRepository} applies
+ * the filter while it pages and while it counts, so the caller never has to hold
+ * more than one page of rows.
+ *
+ * <p>A customer matches when it satisfies both parts:
+ * <ul>
+ * <li><b>Name</b> &mdash; {@link #name()} is split on whitespace, and every term
+ * has to occur in the first or the last name. Comparison ignores case and
+ * accents in both directions, so {@code makinen} and {@code mäkinen} both find
+ * {@code Mäkinen}. Empty text matches everything.</li>
+ * <li><b>Status</b> &mdash; an empty {@link #statuses()} matches every status;
+ * otherwise the customer's status has to be one of them.</li>
+ * </ul>
+ *
+ * @param name     the name terms, whitespace around them insignificant
+ * @param statuses the statuses to keep, empty for all of them
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+    private static final Pattern COMBINING_MARKS = Pattern.compile("\\p{M}+");
+
+    /** The filter that matches every customer. */
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    public CustomerFilter {
+        name = (name == null) ? "" : name.strip();
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : Collections.unmodifiableSet(EnumSet.copyOf(statuses));
+    }
+
+    /** Whether this filter lets every customer through. */
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    /** The name filter as the terms that all have to match, normalised. */
+    public List<String> nameTerms() {
+        if (name.isEmpty()) {
+            return List.of();
+        }
+        return WHITESPACE.splitAsStream(name)
+                .filter(term -> !term.isEmpty())
+                .map(CustomerFilter::normalize)
+                .toList();
+    }
+
+    /**
+     * This filter as a predicate over customers.
+     *
+     * <p>The terms are normalised once here rather than once per customer, so a
+     * backend can hand the result straight to a stream.
+     */
+    public Predicate<Customer> asPredicate() {
+        if (isEmpty()) {
+            return customer -> true;
+        }
+        List<String> terms = nameTerms();
+        Set<CustomerStatus> allowed = statuses;
+        return customer -> matchesStatus(customer, allowed) && matchesName(customer, terms);
+    }
+
+    /** Whether a single customer matches this filter. */
+    public boolean matches(Customer customer) {
+        return asPredicate().test(customer);
+    }
+
+    /**
+     * The case- and accent-insensitive form of a piece of text: accents are
+     * decomposed and their marks dropped, so {@code Mäkinen} and {@code MAKINEN}
+     * both come out as {@code makinen}.
+     */
+    public static String normalize(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return COMBINING_MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+
+    private static boolean matchesStatus(Customer customer, Set<CustomerStatus> allowed) {
+        return allowed.isEmpty() || allowed.contains(customer.status());
+    }
+
+    private static boolean matchesName(Customer customer, List<String> terms) {
+        if (terms.isEmpty()) {
+            return true;
+        }
+        String firstName = normalize(customer.firstName());
+        String lastName = normalize(customer.lastName());
+        return terms.stream().allMatch(term -> firstName.contains(term) || lastName.contains(term));
+    }
+}
