+        nameFilter().fill("virtanen");
+        assertThat(page).hasURL(Pattern.compile(".*/\\?name=virtanen$"));
+        statusFilter().selectItems("ACTIVE");
+        assertThat(page).hasURL(Pattern.compile(".*/\\?name=virtanen&status=ACTIVE$"));
+
+        assertEquals(entriesBefore, historyLength(),
+                "Filtering should replace the history entry, not push a new one");
+    }
+
+    /** The input inside the name field; the field itself carries the placeholder too. */
+    private Locator nameFilter() {
+        return page.locator("vaadin-text-field input[placeholder='Filter by name']");
+    }
+
+    private MultiSelectComboBoxElement statusFilter() {
+        return MultiSelectComboBoxElement.getByLabel(page, "Status");
+    }
+
+    private int historyLength() {
+        return ((Number) page.evaluate("() => history.length")).intValue();
+    }
+}
